  claims: Claim[] | undefined,
  people: Person[] | undefined,
  rates: Rate[] | undefined,
  floor: Floor,
  late: Late,
): string {
  return dueTotal((people ?? []).map((p) => personPeriodDue(period, p, claims, rates, floor, late)));
}
